// UpdateQuizQuestion is the resolver for the updateQuizQuestion field.
func (r *mutationResolver) UpdateQuizQuestion(ctx context.Context, id string, input model.UpdateQuizQuestionInput) (model.QuizQuestion, error) {
	userID, ok := middleware.GetUserID(ctx)
	if !ok || userID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}

	// Load question to get quiz ID
	question, err := r.DB.Queries.GetQuizQuestionByID(ctx, id)
	if err != nil {
		return nil, fmt.Errorf("failed to load question: %w", err)
	}

	// Load quiz to check authorization
	thunk := r.Loaders.QuizByIDLoader.Load(ctx, question.QuizID)
	quiz, err := thunk()
	if err != nil {
		return nil, fmt.Errorf("failed to load quiz: %w", err)
	}

	if !r.RoleService.CanManageProject(ctx, userID, quiz.ProjectID) {
		return nil, fmt.Errorf("unauthorized")
	}

	// Begin transaction
	tx, err := r.DB.Pool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to begin transaction: %w", err)
	}
	defer func() {
		_ = tx.Rollback(ctx)
	}()
	qtx := r.DB.Queries.WithTx(tx)

	// Build update params
	params := sqlc.UpdateQuizQuestionParams{
		ID: id,
	}
	params.Questiontext = input.QuestionText
	if input.QuestionOrder != nil {
		qo := int32(*input.QuestionOrder)
		params.Questionorder = &qo
	}
	if input.AllowMultipleSelection != nil {
		params.Allowmultipleselection = input.AllowMultipleSelection
	}
	if input.MinValue != nil {
		_ = params.Minvalue.Scan(*input.MinValue)
	}
	if input.MaxValue != nil {
		_ = params.Maxvalue.Scan(*input.MaxValue)
	}
	if input.StepValue != nil {
		_ = params.Stepvalue.Scan(*input.StepValue)
	}
	if input.TimeoutSeconds != nil {
		ts := int32(*input.TimeoutSeconds)
		params.Timeoutseconds = &ts
	}
	if input.Points != nil {
		pts := int32(*input.Points)
		params.Points = &pts
	}

	// Set betting configuration
	if input.BettingEnabled != nil {
		params.Bettingenabled = input.BettingEnabled
	}
	if input.BettingMinPercentage != nil {
		_ = params.Bettingminpercentage.Scan(fmt.Sprintf("%f", *input.BettingMinPercentage))
	}
	if input.BettingMaxPercentage != nil {
		_ = params.Bettingmaxpercentage.Scan(fmt.Sprintf("%f", *input.BettingMaxPercentage))
	}
	if input.BettingMinAbsolute != nil {
		minAbs := int32(*input.BettingMinAbsolute)
		params.Bettingminabsolute = &minAbs
	}
	if input.BettingMaxAbsolute != nil {
		maxAbs := int32(*input.BettingMaxAbsolute)
		params.Bettingmaxabsolute = &maxAbs
	}

	// Update question
	updatedQuestion, err := qtx.UpdateQuizQuestion(ctx, params)
	if err != nil {
		return nil, fmt.Errorf("failed to update question: %w", err)
	}

	// If predefined answers provided, replace all answers
	if input.PredefinedAnswers != nil {
		// Delete existing answers
		err = qtx.DeletePredefinedAnswersByQuestion(ctx, id)
		if err != nil {
			return nil, fmt.Errorf("failed to delete existing answers: %w", err)
		}

		// Create new answers
		for _, answerInput := range input.PredefinedAnswers {
			answerID := ulid.NewQuizAnswerID()
			_, err := qtx.CreatePredefinedAnswer(ctx, sqlc.CreatePredefinedAnswerParams{
				ID:          answerID,
				Questionid:  id,
				Answertext:  answerInput.AnswerText,
				Iscorrect:   answerInput.IsCorrect,
				Answerorder: int32(answerInput.AnswerOrder),
			})
			if err != nil {
				return nil, fmt.Errorf("failed to create answer: %w", err)
			}
		}
	}

	// If ordering items provided, replace all items (stored in quiz_predefined_answers table)
	if input.OrderingItems != nil {
		// Delete existing items
		err = qtx.DeletePredefinedAnswersByQuestion(ctx, id)
		if err != nil {
			return nil, fmt.Errorf("failed to delete existing ordering items: %w", err)
		}

		// Create new items
		for _, itemInput := range input.OrderingItems {
			itemID := ulid.NewQuizAnswerID()
			_, err := qtx.CreatePredefinedAnswer(ctx, sqlc.CreatePredefinedAnswerParams{
				ID:          itemID,
				Questionid:  id,
				Answertext:  itemInput.ItemText,
				Iscorrect:   false, // Not used for ordering
				Answerorder: int32(itemInput.CorrectOrder),
			})
			if err != nil {
				return nil, fmt.Errorf("failed to create ordering item: %w", err)
			}
		}
	}

	if err := tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("failed to commit transaction: %w", err)
	}

	r.Cache.InvalidateQuiz(question.QuizID)
	// Also invalidate answers cache if answers or ordering items were updated
	if len(input.PredefinedAnswers) > 0 || len(input.OrderingItems) > 0 {
		r.Cache.InvalidateQuizAnswers(id)
	}

	return convertUpdateQuizQuestionRowToInterface(updatedQuestion), nil
}

