// ReorderQuizQuestions is the resolver for the reorderQuizQuestions field.
func (r *mutationResolver) ReorderQuizQuestions(ctx context.Context, quizID string, questionIds []string) ([]model.QuizQuestion, error) {
	userID, ok := middleware.GetUserID(ctx)
	if !ok || userID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}

	// Load quiz to check authorization
	thunk := r.Loaders.QuizByIDLoader.Load(ctx, quizID)
	quiz, err := thunk()
	if err != nil {
		return nil, fmt.Errorf("failed to load quiz: %w", err)
	}

	if !r.RoleService.CanManageProject(ctx, userID, quiz.ProjectID) {
		return nil, fmt.Errorf("unauthorized")
	}

	// Update order for each question (batch update, not in loop)
	for i, questionID := range questionIds {
		err := r.DB.Queries.UpdateQuizQuestionOrder(ctx, sqlc.UpdateQuizQuestionOrderParams{
			ID:            questionID,
			Questionorder: int32(i),
		})
		if err != nil {
			return nil, fmt.Errorf("failed to update question order: %w", err)
		}
	}

	r.Cache.InvalidateQuiz(quizID)

	// Load and return reordered questions
	thunk2 := r.Loaders.QuizQuestionsByQuizLoader.Load(ctx, quizID)
	questions, err := thunk2()
	if err != nil {
		return nil, fmt.Errorf("failed to load reordered questions: %w", err)
	}

	return questions, nil
}

// CreateQuizAchievement is the resolver for the createQuizAchievement field.
func (r *mutationResolver) CreateQuizAchievement(ctx context.Context, input model.CreateQuizAchievementInput) (*model.QuizAchievement, error) {
	// Get authenticated user ID from context
	userID, ok := middleware.GetUserID(ctx)
	if !ok || userID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}

	// Check authorization
	if !r.RoleService.CanManageProject(ctx, userID, input.ProjectID) {
		return nil, fmt.Errorf("unauthorized to create achievements in this project")
	}

	// Validate that the quiz exists and belongs to the same project
	thunk := r.Loaders.QuizByIDLoader.Load(ctx, input.QuizID)
	quiz, err := thunk()
	if err != nil {
		return nil, fmt.Errorf("failed to load quiz: %w", err)
	}

	if quiz.ProjectID != input.ProjectID {
		return nil, fmt.Errorf("quiz does not belong to the specified project")
	}

	// Validate score percentage if provided
	if input.MinScorePercentage != nil && (*input.MinScorePercentage < 0 || *input.MinScorePercentage > 100) {
		return nil, fmt.Errorf("minScorePercentage must be between 0 and 100")
	}

	// Generate achievement ID
	achievementID := ulid.NewAchievementID()

	// Begin transaction
	tx, err := r.DB.Pool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to begin transaction: %w", err)
	}
	defer tx.Rollback(ctx)

	qtx := r.DB.Queries.WithTx(tx)

	// Create achievement record
	achievementParams := sqlc.CreateAchievementParams{
		ID:                   achievementID,
		ProjectID:            input.ProjectID,
		AchievementType:      "QUIZ",
		Name:                 input.Name,
		DescriptionPending:   input.DescriptionPending,
		DescriptionCompleted: input.DescriptionCompleted,
		ImagePending:         input.ImagePending,
		ImageCompleted:       input.ImageCompleted,
		Points:               int32(input.Points),
		Hidden:               input.Hidden,
	}

	// Inherit challenge from quiz
	achievementParams.ChallengeID = quiz.ChallengeID

	achievementRow, err := qtx.CreateAchievement(ctx, achievementParams)
	if err != nil {
		return nil, fmt.Errorf("failed to create achievement: %w", err)
	}

	// Create quiz_achievement record
	quizAchievementParams := sqlc.CreateQuizAchievementParams{
		Achievementid:     achievementID,
		Quizid:            input.QuizID,
		Requirecompletion: input.RequireCompletion,
	}

	if input.MinScorePercentage != nil {
		msp := int32(*input.MinScorePercentage)
		quizAchievementParams.Minscorepercentage = &msp
	}

	_, err = qtx.CreateQuizAchievement(ctx, quizAchievementParams)
	if err != nil {
		return nil, fmt.Errorf("failed to create quiz achievement: %w", err)
	}

	// Commit transaction
	if err := tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("failed to commit transaction: %w", err)
	}

	// Load challenge to get eventID for cache invalidation
	challengeThunk := r.Loaders.ChallengeByIDLoader.Load(ctx, quiz.ChallengeID)
	challenge, err := challengeThunk()
	if err != nil {
		// Log but don't fail - cache invalidation is secondary
		fmt.Printf("warning: failed to load challenge %s for cache invalidation: %v\n", quiz.ChallengeID, err)
	}

	// Invalidate caches
	r.Cache.InvalidateProject(input.ProjectID)
	if challenge != nil {
		eventID := getChallengeEventID(challenge)
		r.Cache.InvalidateChallenge(quiz.ChallengeID, input.ProjectID, eventID)
	} else {
		r.Cache.InvalidateChallenge(quiz.ChallengeID, input.ProjectID, nil)
	}
	// Invalidate achievements list caches so new achievement appears in queries
	r.Cache.DeletePrefix(cache.PrefixAchievementsFilter)
	r.Cache.DeletePrefix(cache.PrefixAchievementsCount)

	// Convert to GraphQL model
	var minScorePercentage *int
	if input.MinScorePercentage != nil {
		msp := *input.MinScorePercentage
		minScorePercentage = &msp
	}

	hidden := false
	if achievementRow.Hidden != nil {
		hidden = *achievementRow.Hidden
	}

	return &model.QuizAchievement{
		ID:                   achievementID,
		Name:                 achievementRow.Name,
		DescriptionPending:   achievementRow.DescriptionPending,
		DescriptionCompleted: achievementRow.DescriptionCompleted,
		ImagePending:         achievementRow.ImagePending,
		ImageCompleted:       achievementRow.ImageCompleted,
		ProjectID:            achievementRow.ProjectID,
		EventID:              achievementRow.EventID,
		ChallengeID:          achievementRow.ChallengeID,
		Points:               int(achievementRow.Points),
		Hidden:               hidden,
		QuizID:               input.QuizID,
		MinScorePercentage:   minScorePercentage,
		RequireCompletion:    input.RequireCompletion,
	}, nil
}

// SubmitQuizAnswer is the resolver for the submitQuizAnswer field.
func (r *mutationResolver) SubmitQuizAnswer(ctx context.Context, submissionID string, input model.SubmitQuizAnswerInput) (model.QuizResponse, error) {
	ctx, span := otel.StartSpan(ctx, "quiz.submit_answer",
		attribute.String("submission.id", submissionID),
		attribute.String("question.id", input.QuestionID),
	)
	defer span.End()

	userID, ok := middleware.GetUserID(ctx)
	if !ok || userID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}
	otel.SetUserID(span, userID)

	// Load submission
	submission, err := r.DB.Queries.GetQuizSubmissionByID(ctx, submissionID)
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to load submission: %w", err)
	}
	otel.SetQuizID(span, submission.QuizID)

	// Verify ownership
	if submission.UserID != userID {
		return nil, fmt.Errorf("unauthorized")
	}

	// Check not completed
	if submission.CompletedAt.Valid {
		return nil, fmt.Errorf("submission already completed")
	}

	// Check not expired
	if submission.ExpiresAt.Valid && time.Now().After(submission.ExpiresAt.Time) {
		return nil, fmt.Errorf("submission expired")
	}

	// Load question to validate
	question, err := r.DB.Queries.GetQuizQuestionByID(ctx, input.QuestionID)
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to load question: %w", err)
	}
	span.SetAttributes(attribute.String("question.type", question.QuestionType))

	// Check question belongs to quiz
	if question.QuizID != submission.QuizID {
		return nil, fmt.Errorf("question does not belong to this quiz")
	}

	// Validate bet if provided
	if input.BetAmount != nil && *input.BetAmount > 0 {
		// Load quiz to get project ID for score lookup
		quizThunk := r.Loaders.QuizByIDLoader.Load(ctx, submission.QuizID)
		quiz, quizErr := quizThunk()
		if quizErr != nil {
			otel.RecordError(span, quizErr)
			return nil, fmt.Errorf("failed to load quiz for bet validation: %w", quizErr)
		}

		betConfig := BetValidationConfig{
			BettingEnabled:       question.BettingEnabled,
			BettingMinPercentage: question.BettingMinPercentage,
			BettingMaxPercentage: question.BettingMaxPercentage,
			BettingMinAbsolute:   question.BettingMinAbsolute,
			BettingMaxAbsolute:   question.BettingMaxAbsolute,
		}

		if err := ValidateBet(ctx, r.DB.Queries, userID, quiz.ProjectID, betConfig, input.BetAmount); err != nil {
			otel.RecordError(span, err)
			return nil, fmt.Errorf("invalid bet: %w", err)
		}
	}

	// Build response params
	responseID := ulid.NewQuizResponseID()
	params := sqlc.CreateQuizResponseParams{
		ID:           responseID,
		Submissionid: submissionID,
		Questionid:   input.QuestionID,
	}

	// Set type-specific response and calculate correctness
	switch question.QuestionType {
	case "PREDEFINED":
		if input.SelectedAnswerIds != nil {
			selectedJSON, _ := json.Marshal(input.SelectedAnswerIds)
			params.Selectedanswerids = selectedJSON

			// Calculate correctness
			correctAnswers, _ := r.DB.Queries.GetPredefinedAnswersByQuestionID(ctx, input.QuestionID)
			correctIDs := make(map[string]bool)
			for _, ans := range correctAnswers {
				if ans.IsCorrect {
					correctIDs[ans.ID] = true
				}
			}

			// Check if selected answers match correct answers exactly
			if len(input.SelectedAnswerIds) == len(correctIDs) {
				allCorrect := true
				for _, selectedID := range input.SelectedAnswerIds {
					if !correctIDs[selectedID] {
						allCorrect = false
						break
					}
				}
				params.Iscorrect = &allCorrect
			} else {
				falseVal := false
				params.Iscorrect = &falseVal
			}
		}
	case "FREE_TEXT":
		if input.TextResponse != nil {
			params.Textresponse = input.TextResponse
		}
		// FREE_TEXT is not graded - leave is_correct NULL
	case "NUMBER":
		if input.NumberResponse != nil {
			_ = params.Numberresponse.Scan(*input.NumberResponse)
		}
		// NUMBER could be graded if we stored correct answer, but for now leave NULL
	case "JSON":
		if input.JSONResponse != nil {
			params.Jsonresponse = []byte(*input.JSONResponse)
		}
		// JSON is not graded - leave is_correct NULL
	case "ORDERING":
		if input.SubmittedOrder != nil {
			// Store submitted order as JSON in json_response
			orderJSON, _ := json.Marshal(input.SubmittedOrder)
			params.Jsonresponse = orderJSON

			// Calculate correctness by comparing against correct order
			correctAnswers, _ := r.DB.Queries.GetPredefinedAnswersByQuestionID(ctx, input.QuestionID)

			// correctAnswers are returned sorted by answer_order (correct position)
			isCorrect := len(input.SubmittedOrder) == len(correctAnswers)
			if isCorrect {
				for i, ans := range correctAnswers {
					if input.SubmittedOrder[i] != ans.ID {
						isCorrect = false
						break
					}
				}
			}
			params.Iscorrect = &isCorrect
		}
	}

	// Calculate points_earned for correct answers
	if params.Iscorrect != nil && *params.Iscorrect && question.Points != nil {
		params.Pointsearned = question.Points
	}

	if input.TimeSpentSeconds != nil {
		tss := int32(*input.TimeSpentSeconds)
		params.Timespentseconds = &tss
	}

	// Set bet amount if provided
	if input.BetAmount != nil {
		ba := int32(*input.BetAmount)
		params.Betamount = &ba
	}

	// Try to create new response
	response, err := r.DB.Queries.CreateQuizResponse(ctx, params)
	if err != nil {
		// Check for duplicate key error (unique violation on submission_id + question_id)
		var pgErr *pgconn.PgError
		if errors.As(err, &pgErr) && pgErr.Code == "23505" {
			// Race condition: another request created the response first
			// Fetch the existing response and return it
			existing, fetchErr := r.DB.Queries.GetQuizResponseBySubmissionAndQuestion(ctx, sqlc.GetQuizResponseBySubmissionAndQuestionParams{
				Submissionid: submissionID,
				Questionid:   input.QuestionID,
			})
			if fetchErr != nil {
				return nil, fmt.Errorf("failed to fetch existing response: %w", fetchErr)
			}
			r.Cache.InvalidateQuizSubmission(submissionID)
			// Convert existing response to QuizResponse model
			existingAsModel := &sqlc.QuizResponse{
				ID:                existing.ID,
				SubmissionID:      existing.SubmissionID,
				QuestionID:        existing.QuestionID,
				SelectedAnswerIds: existing.SelectedAnswerIds,
				TextResponse:      existing.TextResponse,
				NumberResponse:    existing.NumberResponse,
				JsonResponse:      existing.JsonResponse,
				IsCorrect:         existing.IsCorrect,
				PointsEarned:      existing.PointsEarned,
				AnsweredAt:        existing.AnsweredAt,
				TimeSpentSeconds:  existing.TimeSpentSeconds,
				BetAmount:         existing.BetAmount,
			}
			return convertResponseRowToInterface(existingAsModel, question.QuestionType), nil
		}
		return nil, fmt.Errorf("failed to save response: %w", err)
	}

	r.Cache.InvalidateQuizSubmission(submissionID)

	// Convert response to QuizResponse model
	responseAsModel := &sqlc.QuizResponse{
		ID:                response.ID,
		SubmissionID:      response.SubmissionID,
		QuestionID:        response.QuestionID,
		SelectedAnswerIds: response.SelectedAnswerIds,
		TextResponse:      response.TextResponse,
		NumberResponse:    response.NumberResponse,
		JsonResponse:      response.JsonResponse,
		IsCorrect:         response.IsCorrect,
		PointsEarned:      response.PointsEarned,
		AnsweredAt:        response.AnsweredAt,
		TimeSpentSeconds:  response.TimeSpentSeconds,
		BetAmount:         response.BetAmount,
	}
	return convertResponseRowToInterface(responseAsModel, question.QuestionType), nil
}

// FinalizeQuiz is the resolver for the finalizeQuiz field.
func (r *mutationResolver) FinalizeQuiz(ctx context.Context, submissionID string) (*model.QuizSubmission, error) {
	ctx, span := otel.StartSpan(ctx, "quiz.finalize",
		attribute.String("submission.id", submissionID),
	)
	defer span.End()

	userID, ok := middleware.GetUserID(ctx)
	if !ok || userID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}
	otel.SetUserID(span, userID)

	// Begin transaction first - we need to acquire the lock before validation
	ctx, txSpan := otel.StartSpan(ctx, "quiz.finalize.transaction")
	tx, err := r.DB.Pool.Begin(ctx)
	if err != nil {
		txSpan.End()
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to begin transaction: %w", err)
	}
	txSuccess := false
	defer func() {
		_ = tx.Rollback(ctx)
		otel.SetTransactionSuccess(txSpan, txSuccess)
		txSpan.End()
	}()
	qtx := r.DB.Queries.WithTx(tx)

	// Load submission with FOR UPDATE lock to prevent concurrent finalization
	ctx, loadSpan := otel.StartSpan(ctx, "quiz.finalize.load_submission")
	submission, err := qtx.GetQuizSubmissionByIDForUpdate(ctx, submissionID)
	loadSpan.End()
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to load submission: %w", err)
	}
	otel.SetQuizID(span, submission.QuizID)

	// Verify ownership
	if submission.UserID != userID {
		return nil, fmt.Errorf("unauthorized")
	}

	// Check not already completed
	if submission.CompletedAt.Valid {
		return nil, fmt.Errorf("submission already completed")
	}

	// Check not expired
	if submission.ExpiresAt.Valid && time.Now().After(submission.ExpiresAt.Time) {
		return nil, fmt.Errorf("submission expired")
	}

	// Calculate score using single query (no loop)
	ctx, scoreSpan := otel.StartSpan(ctx, "quiz.finalize.calculate_score")
	scoreResult, err := qtx.CalculateSubmissionScore(ctx, submissionID)
	if err != nil {
		scoreSpan.End()
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to calculate score: %w", err)
	}

	score := int(scoreResult)
	// Use maxScore from submission (stored when session was started)
	var maxScore int
	if submission.MaxScore != nil {
		maxScore = int(*submission.MaxScore)
	}
	scoreSpan.SetAttributes(
		attribute.Int("score.value", score),
		attribute.Int("score.max", maxScore),
	)
	scoreSpan.End()

	// Load quiz for completion points
	thunk := r.Loaders.QuizByIDLoader.Load(ctx, submission.QuizID)
	quiz, err := thunk()
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to load quiz: %w", err)
	}
	otel.SetProjectID(span, quiz.ProjectID)

	// Calculate total points: completion points + per-answer points
	ctx, pointsSpan := otel.StartSpan(ctx, "quiz.finalize.calculate_points")
	perAnswerPoints, err := qtx.CalculateSubmissionPointsFromResponses(ctx, submissionID)
	if err != nil {
		pointsSpan.End()
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to calculate per-answer points: %w", err)
	}
	totalPoints := int32(quiz.CompletionPoints) + perAnswerPoints
	pointsSpan.SetAttributes(
		attribute.Int("points.completion", quiz.CompletionPoints),
		attribute.Int("points.per_answer", int(perAnswerPoints)),
		attribute.Int("points.total", int(totalPoints)),
	)
	pointsSpan.End()

	// Update submission
	ctx, updateSpan := otel.StartSpan(ctx, "quiz.finalize.update_submission")
	now := time.Now()
	scoreVal := int32(score)
	pointsVal := totalPoints
	updatedSubmission, err := qtx.UpdateQuizSubmission(ctx, sqlc.UpdateQuizSubmissionParams{
		ID:            submissionID,
		Completedat:   pgtype.Timestamptz{Time: now, Valid: true},
		Score:         &scoreVal,
		Pointsawarded: &pointsVal,
	})
	updateSpan.End()
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to update submission: %w", err)
	}

	// Create score journal entry if points > 0
	if totalPoints > 0 {
		ctx, journalSpan := otel.StartSpan(ctx, "quiz.finalize.create_score_journal")

		// Load challenge to get event ID
		challengeThunk := r.Loaders.ChallengeByIDLoader.Load(ctx, quiz.ChallengeID)
		challenge, err := challengeThunk()
		if err != nil {
			journalSpan.End()
			otel.RecordError(span, err)
			return nil, fmt.Errorf("failed to load challenge: %w", err)
		}

		journalID := ulid.NewScoreJournalID()
		journalParams := sqlc.CreateScoreJournalEntryParams{
			ID:          journalID,
			ProjectID:   quiz.ProjectID,
			UserID:      userID,
			Points:      totalPoints,
			SourceType:  "QUIZ",
			SourceID:    &quiz.ID,
			Reason:      &quiz.Name,
			ChallengeID: &quiz.ChallengeID,
			EventID:     getChallengeEventID(challenge),
		}

		_, err = qtx.CreateScoreJournalEntry(ctx, journalParams)
		journalSpan.End()
		if err != nil {
			otel.RecordError(span, err)
			return nil, fmt.Errorf("failed to create score journal entry: %w", err)
		}
	}

	// Check quiz achievements and auto-award
	ctx, achSpan := otel.StartSpan(ctx, "quiz.finalize.check_achievements")
	achievements, _ := qtx.GetQuizAchievementsByQuizID(ctx, quiz.ID)
	achSpan.SetAttributes(attribute.Int("achievements.count", len(achievements)))
	achievementsAwarded := 0
	awardedAchievementIDs := make([]string, 0)
	for _, ach := range achievements {
		shouldAward := true

		// Check completion requirement
		if ach.RequireCompletion && !updatedSubmission.CompletedAt.Valid {
			shouldAward = false
		}

		// Check score percentage requirement
		if ach.MinScorePercentage != nil && maxScore > 0 {
			scorePercentage := (float64(score) / float64(maxScore)) * 100
			if scorePercentage < float64(*ach.MinScorePercentage) {
				shouldAward = false
			}
		}

		// Award achievement if criteria met
		if shouldAward {
			err = qtx.AwardUserAchievement(ctx, sqlc.AwardUserAchievementParams{
				UserID:        userID,
				AchievementID: ach.AchievementID,
			})
			if err != nil {
				// Log error but don't fail the entire quiz finalization
				// User still completed the quiz successfully
				fmt.Printf("warning: failed to award achievement %s to user %s: %v\n", ach.AchievementID, userID, err)
			} else {
				achievementsAwarded++
				awardedAchievementIDs = append(awardedAchievementIDs, ach.AchievementID)
			}
		}
	}
	achSpan.SetAttributes(attribute.Int("achievements.awarded", achievementsAwarded))
	achSpan.End()

	// Commit transaction
	if err := tx.Commit(ctx); err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to commit transaction: %w", err)
	}
	txSuccess = true

	// Send push notifications for awarded achievements (after transaction commits) with translations
	if r.PushService != nil && len(awardedAchievementIDs) > 0 {
		go func(achievementIDs []string, targetUserID string) {
			bgCtx := context.Background()
			achRows, err := r.DB.Queries.GetAchievementsByIDs(bgCtx, achievementIDs)
			if err != nil {
				fmt.Printf("warning: failed to load achievements for notifications: %v\n", err)
				return
			}
			for _, ach := range achRows {
				push.SendTranslatedAchievementNotification(r.PushService, r.Loaders, targetUserID, push.AchievementInfo{
					ID:               ach.ID,
					Name:             ach.Name,
					NotificationText: ach.NotificationText,
					ImageCompleted:   ach.ImageCompleted,
				})
			}
		}(awardedAchievementIDs, userID)
	}

	// Auto-complete the associated challenge (after transaction commits)
	ctx, challengeSpan := otel.StartSpan(ctx, "quiz.finalize.complete_challenge")
	_, err = r.DB.Queries.CompleteUserChallenge(ctx, sqlc.CompleteUserChallengeParams{
		Userid:      userID,
		Challengeid: quiz.ChallengeID,
		Completedat: nil, // Use current time
	})
	if err != nil {
		// Log but don't fail - quiz is finalized, challenge completion is secondary
		fmt.Printf("warning: failed to auto-complete challenge %s for user %s: %v\n", quiz.ChallengeID, userID, err)
	}
	challengeSpan.End()

	// Invalidate caches
	ctx, cacheSpan := otel.StartSpan(ctx, "quiz.finalize.cache_invalidation")
	r.Cache.InvalidateQuizSubmission(submissionID)
	r.Cache.InvalidateProject(quiz.ProjectID)

	// Load challenge to get eventID for cache invalidation
	challengeThunk := r.Loaders.ChallengeByIDLoader.Load(ctx, quiz.ChallengeID)
	challenge, challengeErr := challengeThunk()
	if challengeErr != nil {
		fmt.Printf("warning: failed to load challenge %s for cache invalidation: %v\n", quiz.ChallengeID, challengeErr)
		r.Cache.InvalidateChallenge(quiz.ChallengeID, quiz.ProjectID, nil)
	} else {
		eventID := getChallengeEventID(challenge)
		r.Cache.InvalidateChallenge(quiz.ChallengeID, quiz.ProjectID, eventID)
	}

	r.Cache.InvalidateUser(userID)
	cacheSpan.End()

	// Notify Firestore listeners
	go r.FirebaseService.NotifyUserQuizzes(context.Background(), userID)
	// Also notify about achievements if any were awarded
	if len(awardedAchievementIDs) > 0 {
		go r.FirebaseService.NotifyUserAchievements(context.Background(), userID)
	}

	return convertUpdateQuizSubmissionRow(updatedSubmission), nil
}

// CreateQuizSubmission is the resolver for the createQuizSubmission field (M2M).
func (r *mutationResolver) CreateQuizSubmission(ctx context.Context, quizID string, userID string, responses []model.SubmitQuizAnswerInput, completedAt *scalars.DateTime) (*model.QuizSubmission, error) {
	// This is an M2M mutation - authorization is handled by @requireRole directive

	// Load quiz
	thunk := r.Loaders.QuizByIDLoader.Load(ctx, quizID)
	quiz, err := thunk()
	if err != nil {
		return nil, fmt.Errorf("failed to load quiz: %w", err)
	}

	// Load questions
	questionsThunk := r.Loaders.QuizQuestionsByQuizLoader.Load(ctx, quizID)
	questions, err := questionsThunk()
	if err != nil {
		return nil, fmt.Errorf("failed to load questions: %w", err)
	}

	// Build question order (use canonical order, no randomization for M2M submissions)
	questionOrder := make([]string, len(questions))
	for i, q := range questions {
		questionOrder[i] = q.GetID()
	}
	questionOrderJSON, err := json.Marshal(questionOrder)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal question order: %w", err)
	}

	// Calculate max score (sum of points for gradable questions)
	var maxScore int
	for _, q := range questions {
		switch q.(type) {
		case *model.PredefinedQuestion, *model.NumberQuestion, *model.OrderingQuestion:
			if q.GetPoints() != nil {
				maxScore += *q.GetPoints()
			}
		}
	}

	// Begin transaction
	tx, err := r.DB.Pool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to begin transaction: %w", err)
	}
	defer tx.Rollback(ctx)

	qtx := r.DB.Queries.WithTx(tx)

	// Create submission
	submissionID := ulid.NewQuizSubmissionID()
	submissionParams := sqlc.CreateQuizSubmissionParams{
		ID:            submissionID,
		Quizid:        quizID,
		Userid:        userID,
		Questionorder: questionOrderJSON,
		Maxscore:      int32(maxScore),
	}

	submissionRow, err := qtx.CreateQuizSubmission(ctx, submissionParams)
	if err != nil {
		return nil, fmt.Errorf("failed to create submission: %w", err)
	}
	submission := convertCreateQuizSubmissionRow(submissionRow)

	// Create responses for each answer
	score := 0
	for _, responseInput := range responses {
		// Find question by ID
		var foundQuestion model.QuizQuestion
		for _, q := range questions {
			if q.GetID() == responseInput.QuestionID {
				foundQuestion = q
				break
			}
		}

		if foundQuestion == nil {
			return nil, fmt.Errorf("question %s not found in quiz", responseInput.QuestionID)
		}

		questionID := foundQuestion.GetID()

		// Create response based on question type
		responseID := ulid.NewQuizResponseID()
		responseParams := sqlc.CreateQuizResponseParams{
			ID:           responseID,
			Submissionid: submissionID,
			Questionid:   questionID,
		}

		var isCorrect *bool

		switch foundQuestion.(type) {
		case *model.PredefinedQuestion:
			if responseInput.SelectedAnswerIds == nil {
				return nil, fmt.Errorf("selectedAnswerIds required for PREDEFINED question")
			}

			selectedJSON, err := json.Marshal(responseInput.SelectedAnswerIds)
			if err != nil {
				return nil, fmt.Errorf("failed to marshal selected answer IDs: %w", err)
			}
			responseParams.Selectedanswerids = selectedJSON

			// Calculate correctness
			answersThunk := r.Loaders.QuizAnswersByQuestionLoader.Load(ctx, questionID)
			answers, err := answersThunk()
			if err != nil {
				return nil, fmt.Errorf("failed to load answers: %w", err)
			}

			correctAnswerIDs := make(map[string]bool)
			for _, ans := range answers {
				if ans.IsCorrectValue {
					correctAnswerIDs[ans.ID] = true
				}
			}

			selectedMap := make(map[string]bool)
			for _, id := range responseInput.SelectedAnswerIds {
				selectedMap[id] = true
			}

			correct := len(correctAnswerIDs) == len(selectedMap)
			if correct {
				for id := range correctAnswerIDs {
					if !selectedMap[id] {
						correct = false
						break
					}
				}
				for id := range selectedMap {
					if !correctAnswerIDs[id] {
						correct = false
						break
					}
				}
			}

			isCorrect = &correct
			responseParams.Iscorrect = &correct

		case *model.FreeTextQuestion:
			if responseInput.TextResponse == nil {
				return nil, fmt.Errorf("textResponse required for FREE_TEXT question")
			}
			responseParams.Textresponse = responseInput.TextResponse

		case *model.NumberQuestion:
			if responseInput.NumberResponse == nil {
				return nil, fmt.Errorf("numberResponse required for NUMBER question")
			}
			_ = responseParams.Numberresponse.Scan(*responseInput.NumberResponse)

		case *model.JSONQuestion:
			if responseInput.JSONResponse == nil {
				return nil, fmt.Errorf("jsonResponse required for JSON question")
			}
			responseParams.Jsonresponse = []byte(*responseInput.JSONResponse)

		case *model.OrderingQuestion:
			if responseInput.SubmittedOrder == nil {
				return nil, fmt.Errorf("submittedOrder required for ORDERING question")
			}

			// Store submitted order as JSON
			orderJSON, err := json.Marshal(responseInput.SubmittedOrder)
			if err != nil {
				return nil, fmt.Errorf("failed to marshal submitted order: %w", err)
			}
			responseParams.Jsonresponse = orderJSON

			// Calculate correctness
			answersThunk := r.Loaders.QuizAnswersByQuestionLoader.Load(ctx, questionID)
			answers, err := answersThunk()
			if err != nil {
				return nil, fmt.Errorf("failed to load ordering items: %w", err)
			}

			// answers are sorted by answer_order (correct position)
			correct := len(responseInput.SubmittedOrder) == len(answers)
			if correct {
				for i, ans := range answers {
					if responseInput.SubmittedOrder[i] != ans.ID {
						correct = false
						break
					}
				}
			}

			isCorrect = &correct
			responseParams.Iscorrect = &correct
		}

		// Calculate points_earned for correct answers
		if isCorrect != nil && *isCorrect && foundQuestion.GetPoints() != nil {
			pts := int32(*foundQuestion.GetPoints())
			responseParams.Pointsearned = &pts
		}

		if responseInput.TimeSpentSeconds != nil {
			tss := int32(*responseInput.TimeSpentSeconds)
			responseParams.Timespentseconds = &tss
		}

		_, err = qtx.CreateQuizResponse(ctx, responseParams)
		if err != nil {
			return nil, fmt.Errorf("failed to create response: %w", err)
		}

		// Add points earned (already calculated and stored in responseParams.Pointsearned)
		if responseParams.Pointsearned != nil {
			score += int(*responseParams.Pointsearned)
		}
	}

	// Update submission with score if completed
	if completedAt != nil {
		scoreVal := int32(score)
		updateParams := sqlc.UpdateQuizSubmissionParams{
			ID:          submissionID,
			Score:       &scoreVal,
			Completedat: pgtype.Timestamptz{Time: completedAt.Time, Valid: true},
		}

		// Calculate total points: completion points + per-answer points
		perAnswerPoints, err := qtx.CalculateSubmissionPointsFromResponses(ctx, submissionID)
		if err != nil {
			return nil, fmt.Errorf("failed to calculate per-answer points: %w", err)
		}
		totalPoints := int32(quiz.CompletionPoints) + perAnswerPoints

		if totalPoints > 0 {
			updateParams.Pointsawarded = &totalPoints

			// Create score journal entry
			journalID := ulid.NewScoreJournalID()
			_, err = qtx.CreateScoreJournalEntry(ctx, sqlc.CreateScoreJournalEntryParams{
				ID:         journalID,
				ProjectID:  quiz.ProjectID,
				UserID:     userID,
				SourceType: "QUIZ",
				SourceID:   &quizID,
				Points:     totalPoints,
				Reason:     &quiz.Name,
			})
			if err != nil {
				return nil, fmt.Errorf("failed to create score journal entry: %w", err)
			}
		}

		updatedRow, err := qtx.UpdateQuizSubmission(ctx, updateParams)
		if err != nil {
			return nil, fmt.Errorf("failed to update submission with score: %w", err)
		}
		submission = convertUpdateQuizSubmissionRow(updatedRow)
	}

	// Commit transaction
	if err := tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("failed to commit transaction: %w", err)
	}

	// Invalidate caches
	r.Cache.InvalidateQuizSubmission(submissionID)
	r.Cache.InvalidateProject(quiz.ProjectID)

	return submission, nil
}

