// Quizzes is the resolver for the quizzes field.
func (r *queryResolver) Quizzes(ctx context.Context, filter *model.QuizFilter, first *int, after *string, last *int, before *string) (*model.QuizConnection, error) {
	ctx, span := otel.StartSpan(ctx, "quiz.list")
	defer span.End()

	// Build filter params
	var projectID, challengeID *string
	var ids []string

	if filter != nil {
		projectID = filter.ProjectID
		challengeID = filter.ChallengeID
		ids = filter.Ids
		if projectID != nil {
			otel.SetProjectID(span, *projectID)
		}
	}

	// Use cursor pagination pattern from challenges
	limit := 20
	if first != nil && *first > 0 {
		limit = *first
	}
	if last != nil && *last > 0 {
		limit = *last
	}

	// Query database with filter
	params := sqlc.GetQuizzesFilteredCursorParams{
		Querylimit: int32(limit + 1), // +1 to check if there are more
		Isbackward: before != nil,
	}

	if after != nil {
		params.Aftercursor = *after
	}
	if before != nil {
		params.Beforecursor = *before
	}
	if projectID != nil {
		params.Projectid = *projectID
	}
	if challengeID != nil {
		params.Challengeid = *challengeID
	}
	if len(ids) > 0 {
		params.Ids = ids
	}

	rows, err := r.DB.Queries.GetQuizzesFilteredCursor(ctx, params)
	if err != nil {
		return nil, fmt.Errorf("failed to query quizzes: %w", err)
	}

	// Check if there are more results
	hasMore := len(rows) > limit
	if hasMore {
		rows = rows[:limit]
	}

	// Convert rows to models and apply translations
	edges := make([]*model.QuizEdge, len(rows))
	for i, row := range rows {
		quiz := convertFilteredCursorQuizRowToQuiz(row)
		edges[i] = &model.QuizEdge{
			Cursor: row.ID, // Use ID as cursor
			Node:   r.ApplyTranslationToQuiz(ctx, quiz),
		}
	}

	// Build page info
	pageInfo := &model.PageInfo{
		HasNextPage:     hasMore && after != nil,
		HasPreviousPage: hasMore && before != nil,
	}
	if len(edges) > 0 {
		pageInfo.StartCursor = &edges[0].Cursor
		pageInfo.EndCursor = &edges[len(edges)-1].Cursor
	}

	// Get total count
	countParams := sqlc.CountQuizzesFilteredParams{}
	if projectID != nil {
		countParams.Projectid = *projectID
	}
	if challengeID != nil {
		countParams.Challengeid = *challengeID
	}
	if len(ids) > 0 {
		countParams.Ids = ids
	}

	totalCount, err := r.DB.Queries.CountQuizzesFiltered(ctx, countParams)
	if err != nil {
		return nil, fmt.Errorf("failed to count quizzes: %w", err)
	}

	// Convert edges from []*model.QuizEdge to []model.QuizEdge
	edgesVal := make([]model.QuizEdge, len(edges))
	for i, e := range edges {
		edgesVal[i] = *e
	}

	return &model.QuizConnection{
		Edges:      edgesVal,
		PageInfo:   pageInfo,
		TotalCount: int(totalCount),
	}, nil
}

// QuizSubmission is the resolver for the quizSubmission field.
func (r *queryResolver) QuizSubmission(ctx context.Context, id string) (*model.QuizSubmission, error) {
	ctx, span := otel.StartSpan(ctx, "quiz.get_submission",
		attribute.String("submission.id", id),
	)
	defer span.End()

	// Get authenticated user ID
	userID, ok := middleware.GetUserID(ctx)
	if !ok || userID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}
	otel.SetUserID(span, userID)

	// Load submission
	row, err := r.DB.Queries.GetQuizSubmissionByID(ctx, id)
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to load quiz submission: %w", err)
	}
	otel.SetQuizID(span, row.QuizID)

	// Verify user owns this submission (or is admin)
	if row.UserID != userID {
		// Check if user is admin for the quiz's project
		thunk := r.Loaders.QuizByIDLoader.Load(ctx, row.QuizID)
		quiz, err := thunk()
		if err != nil {
			otel.RecordError(span, err)
			return nil, fmt.Errorf("failed to load quiz: %w", err)
		}

		if !r.RoleService.CanManageProject(ctx, userID, quiz.ProjectID) {
			return nil, fmt.Errorf("unauthorized to view this submission")
		}
	}

	return convertGetQuizSubmissionByIDRow(row), nil
}

// QuizSubmissions is the resolver for the quizSubmissions field.
func (r *queryResolver) QuizSubmissions(ctx context.Context, quizID string, userID *string, first *int, after *string, last *int, before *string) (*model.QuizSubmissionConnection, error) {
	ctx, span := otel.StartSpan(ctx, "quiz.list_submissions",
		attribute.String("quiz.id", quizID),
	)
	defer span.End()

	// Get authenticated user ID
	authUserID, ok := middleware.GetUserID(ctx)
	if !ok || authUserID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}
	otel.SetUserID(span, authUserID)

	// Load quiz to check authorization
	thunk := r.Loaders.QuizByIDLoader.Load(ctx, quizID)
	quiz, err := thunk()
	if err != nil {
		return nil, fmt.Errorf("failed to load quiz: %w", err)
	}

	// Only admins can query other users' submissions
	if !r.RoleService.CanManageProject(ctx, authUserID, quiz.ProjectID) {
		return nil, fmt.Errorf("unauthorized to view submissions")
	}

	// Build query params
	limit := 20
	if first != nil && *first > 0 {
		limit = *first
	}
	if last != nil && *last > 0 {
		limit = *last
	}

	params := sqlc.GetQuizSubmissionsFilteredCursorParams{
		Quizid:     quizID,
		Querylimit: int32(limit + 1),
		Isbackward: before != nil,
	}

	if after != nil {
		params.Aftercursor = *after
	}
	if before != nil {
		params.Beforecursor = *before
	}
	if userID != nil {
		params.Userid = *userID
	}

	rows, err := r.DB.Queries.GetQuizSubmissionsFilteredCursor(ctx, params)
	if err != nil {
		return nil, fmt.Errorf("failed to query quiz submissions: %w", err)
	}

	// Check if there are more results
	hasMore := len(rows) > limit
	if hasMore {
		rows = rows[:limit]
	}

	// Convert rows to models
	edges := make([]*model.QuizSubmissionEdge, len(rows))
	for i := range rows {
		edges[i] = &model.QuizSubmissionEdge{
			Cursor: rows[i].ID,
			Node:   convertGetQuizSubmissionsFilteredCursorRow(rows[i]),
		}
	}

	// Build page info
	pageInfo := &model.PageInfo{
		HasNextPage:     hasMore && after != nil,
		HasPreviousPage: hasMore && before != nil,
	}
	if len(edges) > 0 {
		pageInfo.StartCursor = &edges[0].Cursor
		pageInfo.EndCursor = &edges[len(edges)-1].Cursor
	}

	// Get total count
	countParams := sqlc.CountQuizSubmissionsFilteredParams{
		Quizid: quizID,
	}
	if userID != nil {
		countParams.Userid = *userID
	}

	totalCount, err := r.DB.Queries.CountQuizSubmissionsFiltered(ctx, countParams)
	if err != nil {
		return nil, fmt.Errorf("failed to count quiz submissions: %w", err)
	}

	// Convert edges from []*model.QuizSubmissionEdge to []model.QuizSubmissionEdge
	edgesVal := make([]model.QuizSubmissionEdge, len(edges))
	for i, e := range edges {
		edgesVal[i] = *e
	}

	return &model.QuizSubmissionConnection{
		Edges:      edgesVal,
		PageInfo:   pageInfo,
		TotalCount: int(totalCount),
	}, nil
}

